// ─── File: MasterSlaveDemo.java ───
// Runnable demo: writes→master, reads→slaves; kill a slave; kill the master → promote.
package com.bank.masterslave;

import java.math.BigDecimal;
import java.util.logging.*;

public class MasterSlaveDemo {

    private static final Logger log = Logger.getLogger("MasterSlave");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Cluster cluster = new Cluster();
        cluster.initialBalance("SAV2001", new BigDecimal("1000000"));

        // Writes go to master; replicate to slaves; reads come from slaves.
        cluster.write("SAV2001", new BigDecimal("950000"));   // after Rs.50000 transfer
        cluster.replicate();
        log.info(() -> "read from slave: SAV2001 balance = " + cluster.readFromSlave("SAV2001"));

        // 1) A SLAVE dies → reads redistribute, writes unaffected, no data loss.
        cluster.killSlave(0);
        log.warning("slave-1 died → reads shift to remaining replicas (writes unaffected)");
        cluster.write("SAV2001", new BigDecimal("900000"));
        cluster.replicate();
        log.info(() -> "read still works from surviving slave: " + cluster.readFromSlave("SAV2001"));

        // 2) An unreplicated write, then the MASTER dies → risk of losing that write.
        cluster.write("SAV2001", new BigDecimal("880000"));   // NOT yet replicated
        log.warning("master died BEFORE replicating last write (Rs.880000)");
        cluster.killMaster();
        cluster.promoteSlaveToMaster();
        log.severe(() -> "after promotion, new master balance = " + cluster.readFromSlave("SAV2001")
                + " (the unreplicated Rs.880000 write was LOST under async replication)");
    }
}

// ─── node/Master.java (sole writer; keeps replication log) ───
class Master {
    final java.util.Map<String, BigDecimal> data = new java.util.HashMap<>();
    final java.util.List<String> replicationLog = new java.util.ArrayList<>();
    boolean alive = true;
    void write(String acct, BigDecimal bal) {
        if (!alive) throw new IllegalStateException("master down — writes halted");
        data.put(acct, bal);
        replicationLog.add(acct + "=" + bal);   // change recorded for slaves to pull
    }
}

// ─── node/Slave.java (read replica; applies master's log) ───
class Slave {
    final java.util.Map<String, BigDecimal> data = new java.util.HashMap<>();
    boolean alive = true;
    int appliedUpTo = 0;
    void applyFrom(Master master) {
        for (int i = appliedUpTo; i < master.replicationLog.size(); i++) {
            String[] kv = master.replicationLog.get(i).split("=");
            data.put(kv[0], new BigDecimal(kv[1]));
        }
        appliedUpTo = master.replicationLog.size();
    }
    BigDecimal read(String acct) { return data.get(acct); }
}

// ─── cluster/Cluster.java (routes writes→master, reads→slaves; handles failover) ───
class Cluster {
    private static final Logger log = Logger.getLogger("MasterSlave");
    private Master master = new Master();
    private final java.util.List<Slave> slaves =
            new java.util.ArrayList<>(java.util.List.of(new Slave(), new Slave()));
    void initialBalance(String acct, BigDecimal bal) { master.write(acct, bal); replicate(); }
    void write(String acct, BigDecimal bal) { master.write(acct, bal); }   // writes → master only
    void replicate() { for (Slave s : slaves) if (s.alive) s.applyFrom(master); }
    BigDecimal readFromSlave(String acct) {
        for (Slave s : slaves) if (s.alive && s.read(acct) != null) return s.read(acct);
        return master.alive ? master.data.get(acct) : null;   // fall back to master if needed
    }
    void killSlave(int i) { slaves.get(i).alive = false; }
    void killMaster() { master.alive = false; }
    // Promote the most up-to-date surviving slave to be the new master.
    void promoteSlaveToMaster() {
        Slave best = slaves.stream().filter(s -> s.alive)
                .max(java.util.Comparator.comparingInt(s -> s.appliedUpTo)).orElseThrow();
        Master newMaster = new Master();
        newMaster.data.putAll(best.data);                 // only what the slave had replicated
        best.data.forEach((k, v) -> newMaster.replicationLog.add(k + "=" + v));
        this.master = newMaster;
        log.info("promoted most-caught-up slave to new master (fencing prevents split-brain)");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
